20	// Client is an authenticated HTTP client for the Entire API.
21	// It attaches the bearer token to all outgoing requests via the Authorization header.
22	type Client struct {
23		httpClient *http.Client
24		baseURL    string
25	
26		// authSessionsPath is the base path for entire-core's login-session
27		// endpoints (list / revoke / current). Set via WithAuthSessionsPath when the
28		// client targets the auth host; empty otherwise, and the session methods
29		// error out if called against an empty path.
30		authSessionsPath string
31	}
32	
33	// WithAuthSessionsPath sets the base path used by ListAuthSessions,
34	// RevokeCurrentAuthSession, and RevokeAuthSession. Returns the receiver for chaining
35	// at construction:
36	//
37	//	c := api.NewClientWithBaseURL(token, base).WithAuthSessionsPath(p)
38	func (c *Client) WithAuthSessionsPath(path string) *Client {
39		c.authSessionsPath = path
40		return c
41	}
42	
43	// NewClient creates a new authenticated API client with an explicit bearer
44	// token, targeting the data API base URL (BaseURL()).
45	func NewClient(token string) *Client {
46		return NewClientWithBaseURL(token, BaseURL())
47	}
48	
49	// NewClientWithBaseURL creates a new authenticated API client targeting an
50	// explicit base URL. Use this for endpoints that live on a login server
51	// rather than the data API (e.g. auth-session management).
52	func NewClientWithBaseURL(token, baseURL string) *Client {
53		return &Client{
54			httpClient: &http.Client{
55				Transport: &bearerTransport{
56					token: token,
57					base:  http.DefaultTransport,
58				},
59			},
60			baseURL: baseURL,
61		}
62	}
63	
64	// bearerTransport is an http.RoundTripper that injects the Authorization header.
65	//
66	// When token is empty, the Authorization header is omitted (rather than sent
67	// as a malformed "Authorization: Bearer "). This supports endpoints like
68	// recap that deliberately want the unauthenticated request to reach the
69	// server so it can return a typed 401 — callers that want a local fast-fail
70	// for missing auth should check ErrNotLoggedIn at construction time, not
71	// rely on the transport.
72	type bearerTransport struct {
73		token string
74		base  http.RoundTripper
